#include <stdlib.h>
typedef struct{int*val,*mn,top,cap;}MinStack;MinStack* minStackCreate(){MinStack*s=malloc(sizeof(*s));s->cap=16;s->top=0;s->val=malloc(s->cap*sizeof(int));s->mn=malloc(s->cap*sizeof(int));return s;}void minStackPush(MinStack*s,int x){if(s->top==s->cap){s->cap*=2;s->val=realloc(s->val,s->cap*sizeof(int));s->mn=realloc(s->mn,s->cap*sizeof(int));}s->val[s->top]=x;s->mn[s->top]=s->top?(x<s->mn[s->top-1]?x:s->mn[s->top-1]):x;s->top++;}void minStackPop(MinStack*s){s->top--;}int minStackTop(MinStack*s){return s->val[s->top-1];}int minStackGetMin(MinStack*s){return s->mn[s->top-1];}void minStackFree(MinStack*s){free(s->val);free(s->mn);free(s);}
